def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg = next(v for row in grid for v in row if v != bg)
    out = [row[:] for row in grid]
    # Color 2 fills the gaps within each horizontal and vertical run-span.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == fg]
        if cols:
            for c in range(min(cols), max(cols) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == fg]
        if rows:
            for r in range(min(rows), max(rows) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out

