def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    fg = next(v for row in grid for v in row if v != bg)
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == fg]
    r0, r1 = min(r for r,c in pts), max(r for r,c in pts)
    c0, c1 = min(c for r,c in pts), max(c for r,c in pts)
    out = [row[:] for row in grid]
    for r in {r0,r1}:
        cs = [c for c in range(c0,c1+1) if grid[r][c] == fg]
        for a,b in zip(cs,cs[1:]):
            for c in range(a+1,b):
                if grid[r][c] == bg: out[r][c] = 2
    for c in {c0,c1}:
        rs = [r for r in range(r0,r1+1) if grid[r][c] == fg]
        for a,b in zip(rs,rs[1:]):
            for r in range(a+1,b):
                if grid[r][c] == bg: out[r][c] = 2
    return out

